import{z as B,x as d,o as E,c as A,q as n,j as l,D as t,d as e,s as o,S as s,b as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"方差缩减","description":"","frontmatter":{"title":"方差缩减","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/variance-reduction.md","filePath":"quant/variance-reduction.md","lastUpdated":1791063341000}'),m={name:"quant/variance-reduction.md"};function p(h,a,C,c,x,u){const r=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=n('<h1 id="方差缩减" tabindex="-1">方差缩减 <a class="header-anchor" href="#方差缩减" aria-label="Permalink to &quot;方差缩减&quot;">​</a></h1><div class="epigraph"><p>蒙特卡洛的误差是 $\\sqrt{\\mathrm{Var}(\\xi)/N}$。对偶变量、控制变量与重要性采样改的是 $\\xi$ 的方差，不是再多画几条无结构的路径。</p><footer>—— 据 Glasserman, Monte Carlo Methods in Financial Engineering, 2003, 第 4–5 章整理</footer></div><p>上一课<a href="/quant/mc-paths">蒙特卡洛路径</a>给出样本均值与标准误。缺口是：虚值期权、稀有触碰、长到期会使 \\(\\mathrm{Var}(\\xi)\\) 大到 \\(N\\) 无法补。本课只给三条标准缩方差接口，作为定价数学课序的收束。下一课离开随机分析，进入<a href="/quant/three-statements-link">三张表怎么连</a>：公司报表与基本面，不再加期权引擎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>独立再抽样把误差按 \\(1/\\sqrt{N}\\) 降，成本线性。缺口是构造新的 \\(\\tilde\\xi\\)，使 \\(\\mathbb E[\\tilde\\xi]=\\mathbb E[\\xi]\\)（或已知偏差），且 \\(\\mathrm{Var}(\\tilde\\xi)\\lt \\mathrm{Var}(\\xi)\\)。没有无偏性，缩方差会偷偷变成改价格。本课不重写 SDE 离散，只在已经能模拟 \\(\\xi\\) 之后改估计量。</p><p>三条经典手段对应三种结构：对称（对偶）、相关的已知期望（控制）、改抽样测度再加权（重要性）。它们可以叠加，但每加一层都要核验期望不变。</p><h3 id="方差缩减不是「把异常路径删掉」" tabindex="-1">方差缩减不是「把异常路径删掉」 <a class="header-anchor" href="#方差缩减不是「把异常路径删掉」" aria-label="Permalink to &quot;方差缩减不是「把异常路径删掉」&quot;">​</a></h3><p>截尾、winsorize 会改期望，估的不再是原合约。稀有事件要用重要性采样把质量移到支付发生的区域，同时乘 RN 权重，而不是扔掉零支付样本装作方差变小。</p><p><span class="marginnote">控制变量常取同一路径上的欧式 Black 闭式：\\(\\xi\\) 与 \\(C_{\\mathrm{BS}}\\) 高度相关，而 \\(\\mathbb E[C_{\\mathrm{BS}}]\\) 已知。相关来自共同的 \\(W\\)，不是来自回归故事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对偶：用 \\(Z\\) 与 \\(-Z\\) 各走一条 GBM，\\(\\tilde\\xi=\\tfrac12(\\xi(Z)+\\xi(-Z))\\)。支付对 \\(Z\\) 单调时负相关，方差下降。控制：\\(\\tilde\\xi=\\xi-\\beta(C-\\mathbb E[C])\\)，最优 \\(\\beta=\\mathrm{Cov}(\\xi,C)/\\mathrm{Var}(C)\\)，样本内估计 \\(\\beta\\) 即可。重要性：在 \\(\\tilde Q\\) 下抽样，令 \\(\\tilde\\xi=\\xi\\,\\mathrm d Q/\\mathrm d\\tilde Q\\)；\\(\\tilde Q\\) 把漂移推向实值区域。Girsanov 密度正是这个权重——RN 课与换测度课在模拟里落地。</p><p>美式的缩方差更窄：对偶仍可用；控制变量要对每个停时策略保持无偏，设计更硬。本课只要求：任何缩方差不破坏最优停定义里的期望。</p><p><span class="marginnote">数字实例：最优控制变量把方差降到 \\(\\mathrm{Var}(\\xi)(1-\\rho^2)\\)。若 \\(\\xi\\) 与 \\(C\\) 的相关 \\(\\rho=0.95\\)，方差变为原来的 \\(1-0.9025\\approx 0.098\\) 倍，标准误降到约 \\(31\\%\\)——等效于把路径数多用十倍，却一分钱算力都不用加。</span></p>',13)),(E(),l(s,null,{default:t(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20XI%5B%22%E6%94%AF%E4%BB%98%20xi%22%5D%20--%3E%20ANT%5B%22%E5%AF%B9%E5%81%B6%20Z%20%E4%B8%8E%E8%B4%9F%20Z%22%5D%0A%20%20XI%20--%3E%20CV%5B%22%E6%8E%A7%E5%88%B6%E5%8F%98%E9%87%8F%E5%B7%B2%E7%9F%A5%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20XI%20--%3E%20IS%5B%22%E6%94%B9%E6%B5%8B%E5%BA%A6%E5%86%8D%E4%B9%98%E5%AF%86%E5%BA%A6%22%5D%0A%20%20ANT%20--%3E%20VAR%5B%22%E6%96%B9%E5%B7%AE%E4%B8%8B%E9%99%8D%E3%80%81%E6%9C%9F%E6%9C%9B%E4%B8%8D%E5%8F%98%22%5D%0A%20%20CV%20--%3E%20VAR%0A%20%20IS%20--%3E%20VAR%0A%20%20VAR%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E4%B8%89%E5%BC%A0%E8%A1%A8%E6%80%8E%E4%B9%88%E8%BF%9E%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[e("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,[e("对偶利用高斯的中心对称：奇函数部分抵消。看涨对 \\(Z\\) 近似单调，效果好；数字、障碍在边界附近对称被破坏，效果不确定。控制变量是 \\(L^2\\) 投影：把 \\(\\xi\\) 里能被 \\(C\\) 解释的部分减掉，残差正交于 \\(C\\)，方差即残差能量——与"),i("a",{href:"/quant/conditional-expectation-proj"},"条件期望作为投影"),e("同一几何。重要性采样把 \\(Q\\) 换成对支付更友好的 \\(\\tilde Q\\)，权重的二次矩若爆炸，方差反而变大；指数倾斜要有节制。")],-1)),(E(),l(s,null,{default:t(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20XI%5B%22%CE%BE%20%E7%9A%84%E6%80%BB%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20P%5B%22%E5%87%8F%E5%8E%BB%20%CE%B2(C%20%E2%88%92%20E%20C)%20%E7%9A%84%E5%8F%AF%E8%A7%A3%E9%87%8A%E9%83%A8%E5%88%86%22%5D%0A%20%20C%5B%22%E5%B7%B2%E7%9F%A5%E6%9C%9F%E6%9C%9B%E7%9A%84%E6%8E%A7%E5%88%B6%E5%8F%98%E9%87%8F%20C%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20R%5B%22%E6%AE%8B%E5%B7%AE%E6%AD%A3%E4%BA%A4%E4%BA%8E%20C%22%5D%0A%20%20R%20--%3E%20V%5B%22%E6%AE%8B%E5%B7%AE%E6%96%B9%E5%B7%AE%20%3D%20Var(%CE%BE)(1%20%E2%88%92%20%CF%81%C2%B2)%22%5D%0A%20%20V%20--%3E%20Q%5B%22%CF%81%20%E8%B6%8A%E6%8E%A5%E8%BF%91%201%2C%20%E7%BC%A9%E5%BE%97%E8%B6%8A%E7%8B%A0%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">术语翻译：重要性采样就是「把骰子灌铅」——刻意到稀有事件常发的区域抽样，再给每个样本乘回一个权重（两个测度的密度比），把被扭曲的期望扳直。灌铅方向对，方差大降；灌过头，权重忽大忽小，方差反而暴涨。</span></p><p>随机数共用：控制变量与对冲差分一样，必须让 \\(\\xi\\) 与 \\(C\\) 走同一条 \\(W\\)，否则协方差估不准，\\(\\beta\\) 失效。</p><p><span class="marginnote">常见误区：初学者容易以为 \\(\\xi\\) 和 \\(C\\) 各自独立抽路径「更干净」。实际上协方差估计会因此混入两组样本的独立噪声，\\(\\beta\\) 被估歪，减项减错方向——名义上的方差缩减可能悄悄变成方差放大。共用同一条 \\(W\\) 不是偷工，是让相关性能被看见。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把分层、拉丁超立方、拟蒙特卡洛写全，它们改收敛速率，对象仍是同一 \\(\\xi\\)。不讨论机器学习控制变量的最新变体。跳过程上的重要性采样要改泊松强度，只留接口。后课默认：报 MC 价格时允许也应当报缩方差后的标准误；本课程的随机分析到此结束。下一课<a href="/quant/three-statements-link">三张表怎么连</a>把对象换成报表勾稽，定价引擎不再使用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>误差由 \\(\\mathrm{Var}(\\xi)\\) 决定；缩方差改估计量，不改合约。</li><li>对偶用 \\(\\pm Z\\)；控制变量减已知期望的相关项；重要性采样乘 RN 权重。</li><li>删异常路径会改期望，不是缩方差。</li><li>随机分析课序在此收束；下一课进入财务报表。</li><li>出处：Glasserman, Monte Carlo Methods in Financial Engineering, 第 4–5 章。</li></ul>',7))])}const _=B(m,[["render",p]]);export{f as __pageData,_ as default};
